/**
 * Workspace dashboard — an AI-first home, not a metrics console.
 *
 * The order on this page is the argument: what you can do (hero,
 * starters, prompt bar), what you were doing (resume pill, recent
 * conversations), and only then what it costs (plan summary). The
 * previous version of this item led with five stat tiles and five
 * settings links, which reads as an admin console for a product the
 * person hasn't used yet.
 *
 * Everything configurable lives in two consumer-owned seams:
 * `@/lib/dashboard-config` (hero copy, starters, chat base path,
 * shortcuts) and `@/lib/dashboard-data` (`getResume` — what
 * "unfinished work" means for this product). Neither requires editing
 * a file this item ships.
 *
 * Pairs with the `chat` item: the hero's starters and the prompt bar
 * open `${chatBasePath}/<new-uuid>?query=…`, which the chat panel sends
 * as the first turn. Without a chat surface installed, set
 * `chatBasePath` or drop those affordances.
 *
 * Workspace resolution: `requireWorkspace()` is called directly and
 * allowed to throw. The `app-shell` item's layout already guarantees an
 * active workspace before any `(app)` route renders, so a failure here
 * means something is genuinely wrong (a revoked session mid-request),
 * not an empty state — and this item ships an `error.tsx` for exactly
 * that.
 *
 * No `actions.ts`: every read is a plain server-side call with no
 * client-triggered refetch (contrast the `usage` item, whose period
 * selector needs one).
 */

import type { Metadata } from "next";
import { getTimeZone, getTranslations } from "next-intl/server";

import { requireWorkspace } from "@intelligo-dev/auth";
import { getTrialStatus, getWorkspaceBilling } from "@intelligo-dev/billing";
import { listConversations } from "@intelligo-dev/core/conversations";
import { summarizeExecutions } from "@intelligo-dev/executions";

import { DashboardHero } from "@/components/dashboard/dashboard-hero";
import { PlanSummary } from "@/components/dashboard/plan-summary";
import { PromptBar } from "@/components/dashboard/prompt-bar";
import { RecentConversations } from "@/components/dashboard/recent-conversations";
import { Link } from "@/i18n/navigation";
import { dashboardConfig } from "@/lib/dashboard-config";
import { getResume } from "@/lib/dashboard-data";

export async function generateMetadata(): Promise<Metadata> {
  const t = await getTranslations("dashboard");
  return { title: t("meta.title") };
}

/**
 * The first moment of this month where the reader is sitting.
 *
 * The server's own zone is nobody's: it used to decide when "this
 * month" began, so the figure here and the one on the usage page could
 * disagree for a day at every month boundary. next-intl already
 * resolves the reader's zone for formatting; this uses the same one.
 */
async function startOfMonth(): Promise<Date> {
  const timeZone = await getTimeZone();

  /** How far the zone is from UTC at this instant, in milliseconds. */
  const offsetMs = (date: Date) => {
    const parts = new Intl.DateTimeFormat("en-US", {
      timeZone,
      hour12: false,
      year: "numeric",
      month: "2-digit",
      day: "2-digit",
      hour: "2-digit",
      minute: "2-digit",
      second: "2-digit",
    }).formatToParts(date);
    const value = (type: string) =>
      Number(parts.find((part) => part.type === type)?.value ?? "0");
    // The wall clock there, read as if it were UTC, minus the instant.
    return (
      Date.UTC(
        value("year"),
        value("month") - 1,
        value("day"),
        value("hour") % 24,
        value("minute"),
        value("second")
      ) - date.getTime()
    );
  };

  const now = new Date();
  const here = new Intl.DateTimeFormat("en-CA", {
    timeZone,
    year: "numeric",
    month: "2-digit",
  }).formatToParts(now);
  const value = (type: string) =>
    Number(here.find((part) => part.type === type)?.value ?? "0");

  // Midnight on the first, corrected by the offset — twice, because the
  // first correction can land the other side of a DST change.
  const naive = Date.UTC(value("year"), value("month") - 1, 1);
  const guess = naive - offsetMs(new Date(naive));
  return new Date(naive - offsetMs(new Date(guess)));
}

export default async function DashboardPage() {
  const t = await getTranslations("dashboard");
  // Namespace-less: shortcut `titleKey`s are fully qualified so a
  // product can point them at its own namespace.
  const tAny = await getTranslations();
  const { workspace, user } = await requireWorkspace();
  const actor = { workspaceId: workspace.id, userId: user.id };

  const [recent, resume, monthSummary, billing, trial] = await Promise.all([
    listConversations(actor, { limit: 5 }),
    getResume(actor, { chatBasePath: dashboardConfig.chatBasePath }),
    summarizeExecutions(workspace.id, {
      from: await startOfMonth(),
      to: new Date(),
    }),
    getWorkspaceBilling(workspace.id),
    getTrialStatus(workspace.id),
  ]);

  const shortcuts = dashboardConfig.shortcuts ?? [];

  return (
    <div className="flex min-h-full flex-col">
      {/* Bottom padding so the last thing on the page clears the
          composer's band instead of ending flush against it. */}
      <div className="flex-1 px-4 pt-12 pb-8 md:pt-16">
        <DashboardHero resume={resume} />

        <RecentConversations
          conversations={recent.map((conversation) => ({
            id: conversation.id,
            title: conversation.title,
            updatedAt: conversation.updatedAt.toISOString(),
          }))}
        />

        {dashboardConfig.showPlanSummary !== false ? (
          <PlanSummary
            planName={billing.plan?.name ?? t("plan.freeName")}
            billingMode={billing.billingMode}
            charged={monthSummary.totals.charged[0] ?? null}
            requestsThisMonth={monthSummary.totals.count}
            trial={{
              hasTrialCredits: trial.hasTrialCredits,
              status: trial.status,
              creditsRemaining: trial.creditsRemaining,
              initialCredits: trial.initialCredits,
              percentageRemaining: trial.percentageRemaining,
              daysRemaining: trial.daysRemaining,
            }}
          />
        ) : null}

        {shortcuts.length > 0 ? (
          <div className="mx-auto mt-8 flex w-full max-w-2xl flex-wrap justify-center gap-x-6 gap-y-2 text-sm">
            {shortcuts.map((shortcut) => {
              const Icon = shortcut.icon;
              return (
                <Link
                  key={shortcut.href}
                  href={shortcut.href}
                  className="inline-flex items-center gap-1.5 text-muted-foreground transition-colors hover:text-foreground"
                >
                  <Icon className="size-3.5" />
                  {tAny(shortcut.titleKey)}
                </Link>
              );
            })}
          </div>
        ) : null}
      </div>

      <PromptBar />
    </div>
  );
}

{
  "meta": {
    "title": "Dashboard"
  },
  "hero": {
    "title": "What can I help with?",
    "subtitle": "Ask a question, draft something, or pick up where you left off. Every turn is metered against your plan.",
    "resume": "Continue where you left off"
  },
  "starters": {
    "first": "Explain what this workspace can do",
    "second": "Draft a short update for my team",
    "third": "Summarize the key points of an idea"
  },
  "promptBar": {
    "placeholder": "Ask anything…",
    "send": "Send",
    "voiceStart": "Start voice input",
    "voiceStop": "Stop voice input"
  },
  "recent": {
    "title": "Recent",
    "untitled": "New conversation"
  },
  "plan": {
    "title": "Plan & usage",
    "freeName": "Free",
    "subscription": "Subscription billing",
    "credit": "Credit billing",
    "requests": "{count, plural, =0 {No requests this month} one {# request this month} other {# requests this month}}",
    "trialRemaining": "{remaining} of {initial} trial credits left",
    "trialDays": "{days, plural, one {# day left} other {# days left}}",
    "viewUsage": "View usage",
    "viewPlans": "View plans"
  },
  "shortcuts": {
    "artifacts": "Artifacts",
    "usage": "Usage",
    "team": "Team"
  }
}

"use client";

/**
 * Error boundary for the workspace dashboard. Renders the shared `RouteError` from the
 * `route-error` item — install it alongside this one.
 */

import { RouteError } from "@/components/shared/route-error";

export default function SegmentError({
  error,
  reset,
}: {
  error: Error & { digest?: string };
  reset: () => void;
}) {
  return <RouteError error={error} reset={reset} scope="dashboard" />;
}

"use client";

/**
 * The dashboard's primary surface: what this workspace is for, a way
 * back into unfinished work, and three ways to start.
 *
 * Deliberately not a stat wall — plan, spend and token counts are real
 * but secondary information, and they live below in `PlanSummary`. A
 * person opening the app wants to do the thing, not read a meter.
 *
 * Starting a conversation mints a client-side UUID and navigates to
 * `${chatBasePath}/${id}?query=…`; the chat item's panel reads that
 * `query` param and sends it as the first turn, creating the row on the
 * server. Nothing is written here.
 */

import { ArrowRight, Sparkles } from "lucide-react";
import { useTranslations } from "next-intl";

import { useRouter } from "@/i18n/navigation";
import { dashboardConfig } from "@/lib/dashboard-config";
import type { ResumeTarget } from "@/lib/dashboard-data";

interface DashboardHeroProps {
  resume: ResumeTarget | null;
}

export function DashboardHero({ resume }: DashboardHeroProps) {
  const t = useTranslations("dashboard");
  // Namespace-less: hero/starter keys are fully qualified so a product
  // can point them at its own namespace (see `@/lib/dashboard-config`).
  const tAny = useTranslations();
  const router = useRouter();

  const Icon = dashboardConfig.hero?.icon ?? Sparkles;
  const chatBasePath = dashboardConfig.chatBasePath ?? "/chat";
  const starters = (dashboardConfig.starters ?? []).map((key) => tAny(key));

  const title = dashboardConfig.hero?.titleKey
    ? tAny(dashboardConfig.hero.titleKey)
    : t("hero.title");
  const subtitle = dashboardConfig.hero?.subtitleKey
    ? tAny(dashboardConfig.hero.subtitleKey)
    : t("hero.subtitle");

  function start(prompt?: string) {
    const id = crypto.randomUUID();
    router.push(
      prompt
        ? `${chatBasePath}/${id}?query=${encodeURIComponent(prompt)}`
        : `${chatBasePath}/${id}`
    );
  }

  return (
    <div className="mx-auto w-full max-w-4xl text-center">
      <div className="flex justify-center">
        <div className="flex size-16 items-center justify-center rounded-full bg-primary/10">
          <Icon className="size-8 text-primary" strokeWidth={1.75} />
        </div>
      </div>

      <h1 className="mt-6 text-3xl font-semibold tracking-tight md:text-4xl">
        {title}
      </h1>
      <p className="mx-auto mt-3 max-w-2xl text-base text-muted-foreground">
        {subtitle}
      </p>

      {resume ? (
        <button
          type="button"
          onClick={() => router.push(resume.href)}
          // `max-w-full` and a truncating label: a resumed conversation
          // is titled from its first message, which on a phone is wider
          // than the screen and wrapped the pill into a block.
          className="mt-4 inline-flex max-w-full items-center gap-1.5 rounded-full bg-accent/60 px-3.5 py-1.5 text-xs font-medium transition-colors hover:bg-accent"
        >
          <span
            className="size-1.5 shrink-0 rounded-full bg-primary"
            aria-hidden
          />
          <span className="truncate">{resume.label ?? t("hero.resume")}</span>
          <ArrowRight className="size-3.5 shrink-0" />
        </button>
      ) : null}

      {starters.length > 0 ? (
        // Sized to their text rather than to a fixed height: at `h-28`
        // a one-line suggestion sat in a tall empty box, which read as
        // something failing to load.
        <div className="mt-10 grid grid-cols-1 gap-3 sm:grid-cols-3">
          {starters.map((starter, index) => (
            <button
              key={index}
              type="button"
              onClick={() => start(starter)}
              className="group flex min-h-20 items-start justify-between gap-2 rounded-2xl border border-border/60 bg-card p-3.5 text-left text-sm leading-snug text-muted-foreground transition-colors hover:border-border hover:bg-accent/40 hover:text-foreground"
            >
              <span className="line-clamp-3">{starter}</span>
              <ArrowRight
                aria-hidden="true"
                className="mt-0.5 size-3.5 shrink-0 opacity-0 transition-opacity group-hover:opacity-100"
              />
            </button>
          ))}
        </div>
      ) : null}
    </div>
  );
}

"use client";

/**
 * Sticky composer at the bottom of the dashboard — start a conversation
 * from the home page without first navigating to the chat surface.
 *
 * It composes the same primitives the `chat` item's composer does, so
 * the home page behaves like the real thing rather than approximating
 * it: Enter sends and Shift+Enter breaks a line (IME-safe), the
 * textarea grows with its content, and dictation appends to the draft.
 *
 * Like the hero's starter cards, it mints a client-side UUID and
 * navigates to `${chatBasePath}/${id}?query=…`; the chat panel sends
 * that as the first turn. Nothing is written here, so an abandoned
 * prompt leaves no empty conversation behind.
 *
 * No attachments, deliberately: the handoff to the chat surface is a
 * URL, which carries text and nothing else, so a file picked here would
 * be dropped by the navigation that follows. Attachments belong to the
 * conversation, one navigation later.
 */

import { useState } from "react";
import { useTranslations } from "next-intl";

import {
  PromptInput,
  PromptInputFooter,
  PromptInputSubmit,
  PromptInputTextarea,
  PromptInputTools,
} from "@/components/ui/ai-prompt-input";
import { SpeechInput } from "@/components/ui/ai-speech-input";
import { useRouter } from "@/i18n/navigation";
import { dashboardConfig } from "@/lib/dashboard-config";

export function PromptBar() {
  const t = useTranslations("dashboard");
  const router = useRouter();
  const [message, setMessage] = useState("");

  const chatBasePath = dashboardConfig.chatBasePath ?? "/chat";

  return (
    // The band, not just the pill, carries a background: the composer
    // is sticky, so while the page scrolls everything passes underneath
    // it — and with only the pill painted, the plan card and the
    // shortcut row showed through the gutter around it. The gradient
    // ends transparent so the content fades out rather than meeting a
    // hard edge.
    <div className="pointer-events-none sticky bottom-0 bg-gradient-to-t from-background via-background to-transparent px-4 pt-8 pb-6">
      <PromptInput
        className="pointer-events-auto mx-auto w-full max-w-3xl"
        onSubmit={({ text }) => {
          const prompt = (text ?? "").trim();
          if (!prompt) return;
          const id = crypto.randomUUID();
          router.push(
            `${chatBasePath}/${id}?query=${encodeURIComponent(prompt)}`
          );
        }}
      >
        <PromptInputTextarea
          value={message}
          onChange={(event) => setMessage(event.target.value)}
          placeholder={t("promptBar.placeholder")}
          aria-label={t("promptBar.placeholder")}
        />
        <PromptInputFooter>
          <PromptInputTools>
            <SpeechInput
              startLabel={t("promptBar.voiceStart")}
              stopLabel={t("promptBar.voiceStop")}
              onTranscript={(spokenText, isFinal) => {
                if (!isFinal) return;
                const spoken = spokenText.trim();
                if (!spoken) return;
                setMessage((current) =>
                  current ? `${current.replace(/\s+$/, "")} ${spoken}` : spoken
                );
              }}
            />
          </PromptInputTools>
          <PromptInputSubmit
            status="ready"
            label={t("promptBar.send")}
            disabled={!message.trim()}
          />
        </PromptInputFooter>
      </PromptInput>
    </div>
  );
}

"use client";

/**
 * The five most recent conversations, as frameless rows.
 *
 * This is what "recent work" means on an AI product's home page —
 * conversations you can walk back into, not execution records. (The
 * `usage` item's table is the right place for the billing-shaped view
 * of the same activity.)
 *
 * Timestamps render as an absolute date on the server and swap to
 * relative once mounted, since `Date.now()` during render would differ
 * between server and client.
 */

import { useEffect, useState } from "react";
import { MessageSquare } from "lucide-react";
import { useFormatter, useTranslations } from "next-intl";

import { Link } from "@/i18n/navigation";
import { dashboardConfig } from "@/lib/dashboard-config";

export interface RecentConversation {
  id: string;
  title: string | null;
  /** ISO string — server components can't hand a Date to a client one. */
  updatedAt: string;
}

export function RecentConversations({
  conversations,
}: {
  conversations: RecentConversation[];
}) {
  const t = useTranslations("dashboard");
  const format = useFormatter();
  const [now, setNow] = useState<Date | null>(null);
  useEffect(() => setNow(new Date()), []);

  if (conversations.length === 0) return null;

  const chatBasePath = dashboardConfig.chatBasePath ?? "/chat";

  return (
    <div className="mx-auto mt-12 w-full max-w-2xl">
      <p className="px-2 text-xs font-medium uppercase tracking-wide text-muted-foreground">
        {t("recent.title")}
      </p>
      <ul className="mt-2">
        {conversations.map((conversation) => {
          const updated = new Date(conversation.updatedAt);
          return (
            <li key={conversation.id}>
              <Link
                href={`${chatBasePath}/${conversation.id}`}
                className="flex w-full items-center gap-3 rounded-xl px-3 py-2.5 text-left transition-colors hover:bg-accent/40"
              >
                <span className="flex size-7 shrink-0 items-center justify-center rounded-full bg-muted">
                  <MessageSquare className="size-3.5" strokeWidth={2} />
                </span>
                <span className="min-w-0 flex-1 truncate text-sm">
                  {conversation.title ?? t("recent.untitled")}
                </span>
                <span className="shrink-0 text-xs text-muted-foreground">
                  {now
                    ? format.relativeTime(updated, now)
                    : format.dateTime(updated, { dateStyle: "medium" })}
                </span>
              </Link>
            </li>
          );
        })}
      </ul>
    </div>
  );
}

/**
 * Plan, credits and this month's spend — the secondary strip under the
 * dashboard's primary surface. A server component: every number is
 * already resolved by the page.
 *
 * Money arrives as an amount that names its own currency and is
 * rendered through `formatMoney` (`@/lib/format-money`, shipped by the
 * `pricing` item), not against a symbol this file chooses. Install
 * `pricing` alongside this item, or drop the charged figure and its
 * import.
 */

import { getFormatter, getTranslations } from "next-intl/server";

import { Link } from "@/i18n/navigation";
import { Progress } from "@/components/ui/progress";
import { formatMoney, type MoneyLike } from "@/lib/format-money";

export interface PlanSummaryProps {
  planName: string;
  billingMode: "subscription" | "credit";
  /** This month's spend, in micros with its currency. */
  charged?: MoneyLike | null;
  requestsThisMonth: number;
  trial: {
    hasTrialCredits: boolean;
    status: string;
    creditsRemaining: number;
    initialCredits: number;
    percentageRemaining: number;
    daysRemaining: number;
  };
}

export async function PlanSummary({
  planName,
  billingMode,
  charged = null,
  requestsThisMonth,
  trial,
}: PlanSummaryProps) {
  const t = await getTranslations("dashboard");
  const format = await getFormatter();

  const showTrial = trial.hasTrialCredits && trial.status === "active";

  return (
    <div className="mx-auto mt-12 w-full max-w-2xl space-y-3">
      <p className="px-2 text-xs font-medium uppercase tracking-wide text-muted-foreground">
        {t("plan.title")}
      </p>

      <div className="rounded-xl border bg-card px-4 py-3">
        <div className="flex flex-wrap items-baseline justify-between gap-x-6 gap-y-2">
          <div>
            <p className="text-sm font-medium">{planName}</p>
            <p className="text-xs text-muted-foreground">
              {billingMode === "subscription"
                ? t("plan.subscription")
                : t("plan.credit")}
            </p>
          </div>

          <div className="flex items-baseline gap-6 text-sm">
            <span className="text-muted-foreground">
              {t("plan.requests", { count: requestsThisMonth })}
            </span>
            <span className="font-medium">
              {charged ? formatMoney(format, charged) : "—"}
            </span>
          </div>
        </div>

        {showTrial ? (
          <div className="mt-3 space-y-1.5 border-t pt-3">
            <div className="flex items-center justify-between text-xs">
              <span className="text-muted-foreground">
                {t("plan.trialRemaining", {
                  remaining: format.number(trial.creditsRemaining, {
                    notation: "compact",
                    maximumFractionDigits: 1,
                  }),
                  initial: format.number(trial.initialCredits, {
                    notation: "compact",
                    maximumFractionDigits: 1,
                  }),
                })}
              </span>
              <span className="text-muted-foreground">
                {t("plan.trialDays", { days: trial.daysRemaining })}
              </span>
            </div>
            <Progress value={trial.percentageRemaining} />
          </div>
        ) : null}

        <div className="mt-3 flex gap-4 border-t pt-3 text-xs">
          <Link href="/usage" className="text-primary hover:underline">
            {t("plan.viewUsage")}
          </Link>
          <Link href="/pricing" className="text-primary hover:underline">
            {t("plan.viewPlans")}
          </Link>
        </div>
      </div>
    </div>
  );
}

/**
 * Dashboard configuration — consumer-owned, imported by client
 * components (so, like `nav-config.ts`, it may hold React/Lucide
 * component values that must never cross the RSC boundary as props).
 *
 * The shipped defaults render a complete, honest AI-first home with no
 * editing: a hero from this item's own messages, a prompt bar that
 * opens a new conversation, recent conversations, and a compact plan
 * summary. Every part is replaceable here rather than in a component:
 *
 *  - `hero`: icon plus fully-qualified message keys for the title and
 *    subtitle. Point them at your product's namespace to say what this
 *    workspace is actually for.
 *  - `starters`: fully-qualified message keys (the `chatConfig.starters`
 *    contract). Each renders as a card that opens a new conversation
 *    prefilled with that text. Empty hides the grid.
 *  - `chatBasePath`: where the prompt bar and starters send the user.
 *    Defaults to the `chat` item's `/chat`; change it if your chat
 *    surface lives elsewhere, and note that the whole prompt-bar
 *    affordance only makes sense with a chat surface installed.
 *  - `shortcuts`: secondary links under the plan summary.
 *  - `showPlanSummary`: set false for a product that doesn't want
 *    billing state on its home page at all.
 */

import {
  BarChart3,
  FileText,
  Sparkles,
  Users,
  type LucideIcon,
} from "lucide-react";

export interface DashboardShortcut {
  titleKey: string;
  href: string;
  icon: LucideIcon;
}

export interface DashboardConfig {
  hero?: {
    icon?: LucideIcon;
    titleKey?: string;
    subtitleKey?: string;
  };
  /** Fully-qualified message keys, resolved namespace-less. */
  starters?: string[];
  chatBasePath?: string;
  shortcuts?: DashboardShortcut[];
  showPlanSummary?: boolean;
}

export const dashboardConfig: DashboardConfig = {
  hero: {
    icon: Sparkles,
    titleKey: "dashboard.hero.title",
    subtitleKey: "dashboard.hero.subtitle",
  },
  starters: [
    "dashboard.starters.first",
    "dashboard.starters.second",
    "dashboard.starters.third",
  ],
  chatBasePath: "/chat",
  shortcuts: [
    {
      titleKey: "dashboard.shortcuts.artifacts",
      href: "/artifacts",
      icon: FileText,
    },
    { titleKey: "dashboard.shortcuts.usage", href: "/usage", icon: BarChart3 },
    {
      titleKey: "dashboard.shortcuts.team",
      href: "/settings/team",
      icon: Users,
    },
  ],
  showPlanSummary: true,
};

import "server-only";

/**
 * Dashboard data seam — consumer-owned, read by the dashboard page on
 * the server.
 *
 * `getResume` answers "what was this person in the middle of?" The
 * default is the most recently updated conversation, which is right for
 * a generic AI workspace. A product whose work has real structure —
 * a multi-phase assessment, a wizard, a review queue — binds its own
 * notion of progress here and the hero's resume pill picks it up with
 * no component edit:
 *
 *   export async function getResume(actor: ResumeActor) {
 *     const run = await getActiveAssessment(actor.workspaceId, actor.userId);
 *     if (!run) return null;
 *     return {
 *       label: `Phase ${run.phase} of ${run.totalPhases}`,
 *       href: `/chat/${run.conversationId}`,
 *     };
 *   }
 *
 * Return `null` when there is nothing to resume — the pill is hidden
 * rather than rendered empty.
 */

import { listConversations } from "@intelligo-dev/core/conversations";

export interface ResumeActor {
  workspaceId: string;
  userId: string;
}

export interface ResumeTarget {
  /**
   * Plain text for the pill (already localized by whoever produced
   * it). Omit to let the dashboard use its own "continue" copy.
   */
  label?: string;
  /** Locale-less href; `@/i18n/navigation`'s Link localizes it. */
  href: string;
}

export async function getResume(
  actor: ResumeActor,
  options?: { chatBasePath?: string }
): Promise<ResumeTarget | null> {
  const [latest] = await listConversations(actor, { limit: 1 });
  if (!latest) return null;

  const base = options?.chatBasePath ?? "/chat";
  return {
    label: latest.title ?? undefined,
    href: `${base}/${latest.id}`,
  };
}
